<?php

namespace Tests\Concerns;

use Illuminate\Http\UploadedFile;
use PhpOffice\PhpSpreadsheet\Spreadsheet;
use PhpOffice\PhpSpreadsheet\Writer\Xlsx;

/**
 * Builds a REAL .xlsx file for Excel Sync Center feature tests - never
 * Illuminate\Http\Testing\File::fake(), whose randomly-generated bytes
 * are neither a parseable workbook nor detected as
 * application/vnd.openxmlformats-officedocument.spreadsheetml.sheet by
 * Laravel's content-based `mimes:xlsx,xls` rule (App\Http\Requests\Admin\
 * StoreExcelImportRequest). Every Excel Sync Center upload test needs
 * an actual PhpSpreadsheet-readable file, so this lives in one shared
 * trait rather than being re-implemented per test class.
 */
trait BuildsExcelFixtures
{
    /**
     * @param list<string> $headers
     * @param list<list<scalar|null>> $rows
     */
    protected function makeXlsxUpload(array $headers, array $rows, string $filename = 'import.xlsx'): UploadedFile
    {
        $spreadsheet = new Spreadsheet();
        $sheet = $spreadsheet->getActiveSheet();
        $sheet->fromArray($headers, null, 'A1');

        foreach ($rows as $index => $row) {
            $sheet->fromArray($row, null, 'A'.($index + 2));
        }

        $tempPath = tempnam(sys_get_temp_dir(), 'excel_fixture_').'.xlsx';
        (new Xlsx($spreadsheet))->save($tempPath);

        // $test = true bypasses UploadedFile's is_uploaded_file() check,
        // which a genuine HTTP upload satisfies but a locally-written
        // temp file never will - the same reason every other file-
        // upload test in this codebase (e.g. StudentResumeTest) relies
        // on UploadedFile::fake(), which sets this same flag internally.
        return new UploadedFile($tempPath, $filename, 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', null, true);
    }

    /**
     * Reads a streamed Xlsx response's body back into a PhpSpreadsheet
     * instance, for export/template tests that need to assert on
     * actual cell contents rather than just the HTTP envelope.
     */
    protected function spreadsheetFromResponseContent(string $content): Spreadsheet
    {
        $tempPath = tempnam(sys_get_temp_dir(), 'excel_response_').'.xlsx';
        file_put_contents($tempPath, $content);

        $reader = \PhpOffice\PhpSpreadsheet\IOFactory::createReader('Xlsx');
        $reader->setReadDataOnly(true);

        return $reader->load($tempPath);
    }
}
